mapper.insert:


    SELECT
        ISRY_APP.SA_FN_GET_RENU_NO('SS', #{LAST_MDFR_ID}, '') AS SLFRL_SUBSID_NO
    FROM DUAL




/* insertSlfriSubSid - Lee SangHoon */

INSERT INTO AFA500 (    /* 자립장려금 */

    RESRCE_NO           /* 자원번호 */
    ,SLFRL_SUBSID_NO    /* 자립장려금번호 */

    ,APRV_STTS_SE_CD    /* 승인상태구분코드 */
    ,GIVE_YM            /* 지급연월 */
    ,GIVE_AMT           /* 지급금액 */
    ,APLY_DT            /* 신청일시 */
    ,APLY_PIC_NO        /* 신청담당자번호 */
    ,ATFINO             /* 첨부파일번호 */
    ,FRST_RGTR_ID       /* 최초등록자아이디 */
    ,LAST_MDFR_ID       /* 최종수정자아이디 */

)VALUES(

    #{RESRCE_NO}
    ,#{SLFRL_SUBSID_NO}

    ,#{APRV_STTS_SE_CD}
    ,#{GIVE_YM}
    ,#{GIVE_AMT}
    ,TO_DATE(#{APLY_DT},'YYYYMMDDHH24MISS')
    ,#{APLY_PIC_NO}
    ,#{ATFINO}
    ,#{FRST_RGTR_ID}
    ,#{LAST_MDFR_ID}

)

mapper.update:
/* updateSlfriSubSid - Lee SangHoon */
UPDATE AFA500 SET /* 자립장려금 */
APRV_STTS_SE_CD = #{APRV_STTS_SE_CD} /* 승인상태구분코드 */ ,PRGRS_RESULT_CN = #{PRGRS_RESULT_CN} /* 진행경과내용 */ ,ATFINO = #{ATFINO} /* 첨부파일번호 */
,APRV_PIC_NO = #{APRV_PIC_NO} /* 승인담당자번호 */ ,APRV_DT = SYSDATE /* 승인일시 */
,LAST_MDFR_ID = #{LAST_MDFR_ID} /* 최종수정자아이디 */ ,LAST_MDFCN_DT = SYSDATE /* 최종수정일시 */
WHERE 1=1 AND SLFRL_SUBSID_NO = #{SLFRL_SUBSID_NO__origin} AND RESRCE_NO = #{RESRCE_NO__origin}


/* deleteSlfriSubSid - Lee SangHoon */

UPDATE AFA500 SET   /* 자립장려금 */

    DEL_YN = 'Y'                    /* 삭제여부 */
    ,LAST_MDFR_ID = #{LAST_MDFR_ID} /* 최종수정자아이디 */
    ,LAST_MDFCN_DT = SYSDATE        /* 최종수정일시 */

WHERE 1=1
AND SLFRL_SUBSID_NO = #{SLFRL_SUBSID_NO__origin}
AND RESRCE_NO = #{RESRCE_NO__origin}

mapper.insert:

            /* insertSlfriSubSidHstr - Lee SangHoon */

            INSERT INTO AFA501( /* 자립장려금 이력 */

                SLFRL_SUBSID_NO     /* 자립장려금번호 */
				,RESRCE_NO          /* 자원번호 */
				,MDFCN_DT           /* 수정일시 */

				,APRV_STTS_SE_CD    /* 승인상태구분코드 */
				,GIVE_YM            /* 지급연월 */
				,GIVE_AMT           /* 지급금액 */
				,APLY_DT            /* 신청일시 */
				,APLY_PIC_NO        /* 신청담당자번호 */
				,APRV_DT            /* 승인일시 */
				,APRV_PIC_NO        /* 승인담당자번호 */
				,PRGRS_RESULT_CN    /* 진행결과내용 */



				,DEL_YN             /* 삭제여부 */



				,ATFINO             /* 첨부파일번호 */
				,FRST_RGTR_ID       /* 최초등록자아이디 */



				,FRST_REG_DT        /* 최초등록일시 */



				,LAST_MDFR_ID       /* 최종수정자아이디 */

			)VALUES(

                #{SLFRL_SUBSID_NO}
                ,#{RESRCE_NO}
                ,SYSDATE

                ,#{APRV_STTS_SE_CD}
                ,#{GIVE_YM}
                ,#{GIVE_AMT}
                ,TO_DATE(#{APLY_DT},'YYYYMMDDHH24MISS')
                ,#{APLY_PIC_NO}
                ,TO_DATE(#{APRV_DT},'YYYYMMDDHH24MISS')
                ,#{APRV_PIC_NO}
                ,#{PRGRS_RESULT_CN}



                ,#{DEL_YN}



                ,#{ATFINO}
                ,#{FRST_RGTR_ID}



                ,TO_DATE(#{FRST_REG_DT},'YYYYMMDDHH24MISS')



                ,#{LAST_MDFR_ID}

			)

mapper.select:

/* selectSlfriSubSidCheck - Lee SangHoon */

SELECT

    APRV_STTS_SE_CD

FROM AFA500

WHERE RESRCE_NO = #{RESRCE_NO}
AND GIVE_YM = #{GIVE_YM}
AND DEL_YN = 'N'
AND APRV_STTS_SE_CD != '3'
